from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    # Find uniform interior row or column as separator.
    for r in range(1, h-1):
        if len(set(grid[r])) == 1:
            split = ('h', r); break
    if split is None:
        for c in range(1, w-1):
            if len({grid[r][c] for r in range(h)}) == 1:
                split = ('v', c); break
    if split is None: raise ValueError('no divider')
    if split[0] == 'h':
        r=split[1]; a=grid[:r]; b=grid[r+1:]
        if len(a)!=len(b) or any(len(x)!=len(y) for x,y in zip(a,b)): raise ValueError('unequal halves')
        ba=Counter(v for row in a for v in row).most_common(1)[0][0]
        bb=Counter(v for row in b for v in row).most_common(1)[0][0]
        return [[2 if x!=ba and y!=bb else 0 for x,y in zip(ra,rb)] for ra,rb in zip(a,b)]
    c=split[1]; a=[row[:c] for row in grid]; b=[row[c+1:] for row in grid]
    if any(len(x)!=len(y) for x,y in zip(a,b)): raise ValueError('unequal halves')
    ba=Counter(v for row in a for v in row).most_common(1)[0][0]
    bb=Counter(v for row in b for v in row).most_common(1)[0][0]
    return [[2 if x!=ba and y!=bb else 0 for x,y in zip(ra,rb)] for ra,rb in zip(a,b)]

